import Mathlib

def I : Set ℤ := {x | 1 ≤ x ∧ x ≤ 100}

def A : Set ℤ := {m | 1 ≤ m ∧ m ≤ 100 ∧ ∃ k, m = 2 * k + 1}

def B : Set ℤ := {n | 1 ≤ n ∧ n ≤ 100 ∧ ∃ k, n = 3 * k}

/- 6. Given the universal set $I=\{x \mid 1 \leqslant x \leqslant 100, x \in \mathbf{Z}\}$ and its two subsets $A=\{m \mid 1 \leqslant m \leqslant$ $100, m=2 k+1, k \in \mathbf{Z}\}, B=\{n \mid 1 \leqslant n \leqslant 100, n=3 k, k \in \mathbf{Z}\}$, the largest element in $\bar{A} \cap B$ is $\qquad$ . -/
theorem number_theory_144063 :
    IsGreatest {x | x ∈ I ∧ ¬x ∈ A ∧ x ∈ B} 96 := by
